#include <iostream>
#include <memory>

class ResourceTracker {
public:
    ResourceTracker() { std::cout << "Resource created\n"; }
    ~ResourceTracker() { std::cout << "Resource destroyed\n"; }
};

int main() {
    std::cout << "--- Manual array allocation with delete[] ---\n";
    ResourceTracker* manualArray = new ResourceTracker[2];
    // Explicitly call delete[] to invoke all destructors
    delete[] manualArray;

    std::cout << "\n--- Modern RAII with std::unique_ptr ---\n";
    {
        auto smartArray = std::make_unique<ResourceTracker[]>(2);
        // smartArray automatically calls delete[] when exiting this scope
    }
    std::cout << "Exited unique_ptr scope successfully.\n";

    return 0;
}

#include <iostream>
#include <iomanip>
#include <stdexcept>

class Array {
    friend std::ostream& operator<<(std::ostream& output, const Array& a) {
        for (size_t i = 0; i < a.size; ++i) {
            output << std::setw(12) << a.ptr[i];
            if ((i + 1) % 4 == 0) output << "\n";
        }
        if (a.size % 4 != 0) output << "\n";
        return output;
    }

    friend std::istream& operator>>(std::istream& input, Array& a) {
        for (size_t i = 0; i < a.size; ++i) {
            input >> a.ptr[i];
        }
        return input;
    }

private:
    size_t size;
    int* ptr;

public:
    explicit Array(int arraySize = 10)
        : size(arraySize > 0 ? static_cast<size_t>(arraySize) : 10),
          ptr(new int[size]{}) {}

    Array(const Array& arrayToCopy)
        : size(arrayToCopy.size), ptr(new int[size]) {
        for (size_t i = 0; i < size; ++i) {
            ptr[i] = arrayToCopy.ptr[i];
        }
    }

    ~Array() {
        delete[] ptr;
    }

    size_t getSize() const { return size; }

    const Array& operator=(const Array& right) {
        if (&right != this) {
            if (size != right.size) {
                delete[] ptr;
                size = right.size;
                ptr = new int[size];
            }
            for (size_t i = 0; i < size; ++i) {
                ptr[i] = right.ptr[i];
            }
        }
        return *this;
    }

    bool operator==(const Array& right) const {
        if (size != right.size) return false;
        for (size_t i = 0; i < size; ++i) {
            if (ptr[i] != right.ptr[i]) return false;
        }
        return true;
    }

    bool operator!=(const Array& right) const {
        return !(*this == right);
    }

    int& operator[](int subscript) {
        if (subscript < 0 || static_cast<size_t>(subscript) >= size) {
            throw std::out_of_range("Subscript out of range");
        }
        return ptr[subscript];
    }

    int operator[](int subscript) const {
        if (subscript < 0 || static_cast<size_t>(subscript) >= size) {
            throw std::out_of_range("Subscript out of range");
        }
        return ptr[subscript];
    }
};

int main() {
    Array integers1(7);
    Array integers2; // 10 elements default

    std::cout << "Size of Array integers1 is " << integers1.getSize()
              << "\nArray after initialization:\n" << integers1;

    integers1[5] = 13;
    Array integers3(integers1);
    std::cout << "Size of Array integers3 is " << integers3.getSize()
              << "\nArray after initialization:\n" << integers3;

    // Test assignment operator resizing
    integers1 = integers2;
    std::cout << "integers1 size after assigning integers2: " << integers1.getSize() << "\n";

    // Test out of range handling
    try {
        std::cout << "Attempting out-of-range assignment to integers1[15]...\n";
        integers1[15] = 1000;
    } catch (const std::out_of_range& ex) {
        std::cout << "An exception occurred: " << ex.what() << "\n";
    }

    return 0;
}
